def _predicate(program,features):
    if not isinstance(program,dict):
        return False
    kind=program.get('kind')
    if kind=='BOOL_TABLE':
        signals=program.get('signals') or []
        if len(signals)<2:return False
        a=bool(features.get(signals[0],False)); b=bool(features.get(signals[1],False))
        return bool((program.get('table') or {}).get(f'{int(a)}{int(b)}',False))
    if kind=='LINEAR_THRESHOLD':
        signals=program.get('signals') or []; weights=program.get('weights') or []
        if len(signals)!=len(weights):return False
        try: score=sum(float(w)*float(features.get(k,0)) for w,k in zip(weights,signals))
        except (TypeError,ValueError):return False
        return score>float(program.get('threshold',0.0))
    return False

def predict_logic_component(model,features):
    if not isinstance(model,dict):return False
    op=model.get('op')
    if op=='LEAF':
        family=(model.get('algorithm') or {}).get('family')
        if family=='ENUM_BOOLEAN':return bool(eval_bool(model.get('model'),features))
        return bool(tree_predict(model.get('model'),features))
    if op=='IF_SIGNAL':
        s=model.get('signal') or {}; key=s.get('key'); th=float(s.get('threshold',.5))
        try:v=float(features.get(key,0))
        except (TypeError,ValueError):v=0.0
        return predict_logic_component(model.get('then') if v>th else model.get('else'),features)
    if op=='IF_PREDICATE':
        return predict_logic_component(model.get('then') if _predicate(model.get('predicate_program'),features) else model.get('else'),features)
    return False

def predict_intel_component(model,features):
    if not isinstance(model,dict):return None
    op=model.get('op')
    if op=='LEAF':
        family=(model.get('algorithm') or {}).get('family')
        return linear_predict(model.get('model'),features) if family=='LINEAR_SCORE_SEARCH' else tree_predict(model.get('model'),features)
    if op=='IF_SIGNAL':
        s=model.get('signal') or {}; key=s.get('key'); th=float(s.get('threshold',.5))
        try:v=float(features.get(key,0))
        except (TypeError,ValueError):v=0.0
        return predict_intel_component(model.get('then') if v>th else model.get('else'),features)
    if op=='IF_PREDICATE':
        return predict_intel_component(model.get('then') if _predicate(model.get('predicate_program'),features) else model.get('else'),features)
    return None

def _thinking_leaf_fit(episodes,algs):
    traces=[]
    for episode in episodes:
        if len(episode)<2 or not isinstance(episode[1],list):continue
        seq=episode[1]
        if seq and isinstance(seq[0],dict):traces.append([str(a.get('role')) for a in seq])
        else:traces.append([str(v) for v in seq])
    best=None
    for spec in algs:
        if spec.get('family')!='GLOBAL_PRECEDENCE':continue
        edges=learn_edges(traces,float(spec.get('threshold',.5)),int(spec.get('min_support',2)))
        leaf={'op':'LEAF','algorithm':dict(spec),'model':edges}
        acc=thinking_component_acc(leaf,episodes)
        candidate=(acc,-len(edges),cj(leaf),leaf)
        if best is None or candidate[:3]>best[:3]:best=candidate
    return best[3] if best else {'op':'LEAF','algorithm':{'family':'GLOBAL_PRECEDENCE'},'model':[]}

def fit_thinking_skeleton(skeleton,episodes,algs):
    def rec(node,rows):
        if not rows or node.get('op')=='LEAF':return _thinking_leaf_fit(rows,algs)
        if node.get('op')!='IF_SIGNAL':return None
        signal=node.get('signal') or {}; key=signal.get('key'); th=float(signal.get('threshold',.5))
        left=[]; right=[]
        for e in rows:
            ctx=e[0] if e and isinstance(e[0],dict) else {}
            try:v=float(ctx.get(key,0))
            except (TypeError,ValueError):v=0.0
            (left if v>th else right).append(e)
        if not left or not right:return None
        return {'op':'IF_SIGNAL','signal':dict(signal),'then':rec(node['then'],left),'else':rec(node['else'],right)}
    return rec(skeleton,list(episodes))

def _thinking_predict(model,episode):
    ctx=episode[0] if episode and isinstance(episode[0],dict) else {}
    if model.get('op')=='IF_SIGNAL':
        s=model.get('signal') or {}; key=s.get('key'); th=float(s.get('threshold',.5))
        try:v=float(ctx.get(key,0))
        except (TypeError,ValueError):v=0.0
        return _thinking_predict(model.get('then') if v>th else model.get('else'),episode)
    if model.get('op')=='IF_PREDICATE':
        return _thinking_predict(model.get('then') if _predicate(model.get('predicate_program'),ctx) else model.get('else'),episode)
    if len(episode)<3:return [],[]
    inp=episode[1]; expected=list(episode[2])
    if inp and isinstance(inp[0],dict):
        actions=inp
    else:
        actions=[{'id':str(i),'role':role} for i,role in enumerate(inp)]
    ids=plan_with_edges(actions,model.get('model',[])); roles={str(a['id']):str(a['role']) for a in actions}
    return [roles[i] for i in ids],expected

def rec(node,rows):
        if not rows or node.get('op')=='LEAF':return _thinking_leaf_fit(rows,algs)
        if node.get('op')!='IF_SIGNAL':return None
        signal=node.get('signal') or {}; key=signal.get('key'); th=float(signal.get('threshold',.5))
        left=[]; right=[]
        for e in rows:
            ctx=e[0] if e and isinstance(e[0],dict) else {}
            try:v=float(ctx.get(key,0))
            except (TypeError,ValueError):v=0.0
            (left if v>th else right).append(e)
        if not left or not right:return None
        return {'op':'IF_SIGNAL','signal':dict(signal),'then':rec(node['then'],left),'else':rec(node['else'],right)}

def baseline_thinking(train,blind):
    # Old global precedence; the old single-marker contextual family has no external-context key learner.
    traces=[expected for _,_,expected in train]
    best=None
    for th in (0.5,0.6,0.67,0.75,0.8,1.0):
        m=learn_edges(traces,threshold=th,min_support=2)
        def acc(data):
            ok=0
            for _,actions,expected in data:
                ids=plan_with_edges(actions,m); by={a['id']:a['role'] for a in actions}
                ok += [by[i] for i in ids]==expected
            return ok/len(data)
        a=acc(train); cand=(a,-len(m),th,m)
        if best is None or cand[:3]>best[:3]: best=cand
    m=best[3]
    ok=0
    for _,actions,expected in blind:
        ids=plan_with_edges(actions,m);by={a['id']:a['role'] for a in actions};ok += [by[i] for i in ids]==expected
    return ok/len(blind)

def learn_multicontext_precedence(episodes, threshold: float = 0.75, min_support: int = 2, max_context_keys: int = 3):
    """Learn separate precedence graphs for bounded context signatures.

    Episode format: (context_mapping_or_iterable, successful_role_trace).
    Context keys are selected only by coverage, not by target ordering.
    """
    if not episodes:
        return {'kind': 'MULTICONTEXT_PRECEDENCE', 'context_keys': [], 'graphs': {}, 'fallback_edges': []}
    contexts = []
    traces = []
    for ctx, trace in episodes:
        if isinstance(ctx, Mapping):
            c = {str(k): bool(v) for k, v in ctx.items()}
        else:
            c = {str(k): True for k in ctx}
        contexts.append(c)
        traces.append([str(r) for r in trace])
    key_counts = Counter(k for c in contexts for k, v in c.items() if v)
    keys = [k for k, _ in sorted(key_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:max_context_keys]]
    grouped: dict[str, list[list[str]]] = defaultdict(list)
    for c, trace in zip(contexts, traces):
        sig = ''.join('1' if c.get(k, False) else '0' for k in keys)
        grouped[sig].append(trace)
    graphs = {}
    for sig, group in sorted(grouped.items()):
        if len(group) >= min_support:
            graphs[sig] = learn_edges(group, threshold=threshold, min_support=min_support)
    return {
        'kind': 'MULTICONTEXT_PRECEDENCE',
        'context_keys': keys,
        'graphs': graphs,
        'fallback_edges': learn_edges(traces, threshold=threshold, min_support=min_support),
        'threshold': float(threshold),
        'min_support': int(min_support),
    }

def _rebuild_semantic_edges(self, threshold: float = 0.55) -> None:
        self.graph.remove_edges_from(list(self.graph.edges))
        if len(self.data_points) < 2:
            return
        sims = cosine_similarity(self.data_points)
        for i in range(len(self.resource_ids)):
            for j in range(i + 1, len(self.resource_ids)):
                score = float(sims[i, j])
                if score >= threshold:
                    self.graph.add_edge(
                        self.resource_ids[i], self.resource_ids[j],
                        weight=score, relation="semantic_similarity", tags=["auto"],
                    )

def _tree_predict_obj(node: Mapping[str, Any], x: Mapping[str, float]) -> str:
        cur: Mapping[str, Any] = node
        while "label" not in cur:
            feature = str(cur["feature"])
            threshold = float(cur["threshold"])
            cur = cur["left"] if float(x.get(feature, 0.0)) <= threshold else cur["right"]
        return str(cur["label"])

class UnifiedYADOKernelV30Candidate(UnifiedYADOKernelV29TraceCrystallization):
    SCHEMA_VERSION=12
    PROFILE='YADO_V3_0_RC1_CONTROLLED_DURABLE_LOCAL'
    def __init__(self,db_path='yado_v30_candidate.db',state_path:str|None=None):
        super().__init__(db_path=db_path); self.state_path=Path(state_path) if state_path else DEFAULT_STATE
        self.canonical_state=self._load_state()
    def _load_state(self)->dict[str,Any]:
        if not self.state_path.exists(): return {'version':'2.9','canonical_durable_mutation':False,'learned_atom_registry':[]}
        return json.loads(self.state_path.read_text(encoding='utf-8'))
    def reload_canonical_state(self): self.canonical_state=self._load_state(); return self.canonical_state
    def call_learned_primitive(self,primitive_id:str,*args:int)->int:
        for p in self.canonical_state.get('learned_atom_registry',[]):
            if p.get('primitive_id')==primitive_id:
                if len(args)!=int(p['arity']): raise ValueError('arity')
                return _eval(p['microprogram'],tuple(args))
        raise KeyError(primitive_id)
    def epistemic_decision(self,calibrated_confidence:float,distance_ratio:float,train_output_unique:int)->str:
        p=self.canonical_state.get('epistemic_policy') or {}
        ok=(calibrated_confidence>=float(p.get('p_threshold',1.1)) and distance_ratio<=float(p.get('distance_threshold',-1)))
        if p.get('require_output_variation') and train_output_unique<2: ok=False
        if p.get('require_lattice_support') is True:
            # lattice support requires a richer query object; fail closed in this compact API
            ok=False
        return 'ACCEPT_REVERSIBLE' if ok else 'SEEK_MORE_EVIDENCE'
    def dynamic_domains(self):
        return dict(self.canonical_state.get('dynamic_domain_registry') or {})
    def execute_dynamic_domain(self,domain_id:str,*args:int)->int:
        d=self.dynamic_domains().get(domain_id)
        if d is None: raise KeyError(domain_id)
        return self.call_learned_primitive(d['primitive_id'],*args)
    def unified_snapshot(self):
        s=super().unified_snapshot(); s.update({
          'profile':self.PROFILE,
          'active_lineage':'YADO_V2_9_TRACE_CRYSTALLIZATION -> YADO_V3_0_RC1_CONTROLLED_DURABLE_LOCAL',
          'canonical_durable_mutation':bool(self.canonical_state.get('canonical_durable_mutation',False)),
          'canonical_state_version':self.canonical_state.get('version'),
          'learned_atomic_primitives':len(self.canonical_state.get('learned_atom_registry',[])),
          'calibrated_epistemic_policy_active':bool(self.canonical_state.get('epistemic_policy')),
          'promotion_scope':self.canonical_state.get('promotion_scope','NONE'),
        }); return s

def epistemic_decision(self,calibrated_confidence:float,distance_ratio:float,train_output_unique:int)->str:
        p=self.canonical_state.get('epistemic_policy') or {}
        ok=(calibrated_confidence>=float(p.get('p_threshold',1.1)) and distance_ratio<=float(p.get('distance_threshold',-1)))
        if p.get('require_output_variation') and train_output_unique<2: ok=False
        if p.get('require_lattice_support') is True:
            # lattice support requires a richer query object; fail closed in this compact API
            ok=False
        return 'ACCEPT_REVERSIBLE' if ok else 'SEEK_MORE_EVIDENCE'

def shadow_evolve_thinking(self,successful_traces:Sequence[Sequence[str]],blind:Sequence[Tuple[Sequence[Mapping[str,str]],Sequence[str]]],capability='learned_planning')->Dict[str,Any]:
        min_n=int(self.canonical_state.get('organ_autoevolution_policy',{}).get('minimum_evidence',{}).get('THINKING',4))
        if len(successful_traces)<min_n:return {'verdict':'INSUFFICIENT_EVIDENCE','organ':'THINKING'}
        # threshold is selected only from revealed traces by maximum retained causal constraints.
        choices=[]
        for th in (.5,.6,.67,.75,.8,1.0):
            ed=learn_edges(successful_traces,th); choices.append((len(ed),th,ed))
        _,th,edges=max(choices,key=lambda z:(z[0],z[1]))
        def acc(ed):
            ok=0
            for actions,expected in blind:
                ids=plan_with_edges(actions,ed); rb={str(a['id']):str(a['role']) for a in actions};ok += [rb[i] for i in ids]==list(expected)
            return ok/max(1,len(blind))
        bl=acc(edges); base=acc(self.models['THINKING_PRECEDENCE_GRAPH']);restore=bl
        verdict='SHADOW_SUPPORTED' if bl==1 and bl>base else 'WITHHOLD'
        cid=self._store_candidate('THINKING',capability,edges,1.0,bl,base,restore,verdict)
        return {'organ':'THINKING','candidate_id':cid,'model':edges,'selected_threshold':th,'train':1.0,'blind':bl,'ablation':base,'restore':restore,'verdict':verdict}

class UnifiedYADOKernelV30RC4MetaAutoEvolution(UnifiedYADOKernelV30RC3Trained):
    PROFILE='YADO_V3_0_RC4_BOUNDED_EVOLUTION_OF_EVOLUTION_LOCAL'
    SCHEMA_VERSION=17
    def __init__(self,db_path='yado_v30_rc4_meta.db',state_path:str|None=None):
        super().__init__(db_path=db_path,state_path=state_path or str(DEFAULT_STATE))
    def organ_evolution_algorithm_bank(self):
        return dict(self.canonical_state.get('organ_evolution_algorithm_bank') or {})
    def _algs(self,organ):return list(self.organ_evolution_algorithm_bank().get(organ,[]))

    def meta_evolve_logic(self,fit,validation,revealed_train,blind):
        candidates=[]
        for a in self._algs('LOGIC'):
            fam=a['family']
            if fam=='ENUM_BOOLEAN':
                model,meta=bounded_enum(fit,int(a.get('max_depth',3)),float(a.get('timeout_s',1.5)))
                val=0.0 if model is None else score_bool(model,validation)
            elif fam=='BOOL_DECISION_TREE':
                model=fit_bool_tree(fit,int(a['max_depth']));meta={};val=acc_logic_model(fam,model,validation)
            else:continue
            candidates.append({'algorithm':a,'model':model,'validation':val,'meta':meta})
        if not candidates:raise RuntimeError('no LOGIC meta algorithms')
        sel=max(candidates,key=lambda z:(z['validation'],z['algorithm']['family']=='ENUM_BOOLEAN',-(z['algorithm'].get('max_depth') or 99)))
        a=sel['algorithm'];fam=a['family']
        if fam=='ENUM_BOOLEAN':model,_=bounded_enum(revealed_train,int(a.get('max_depth',3)),float(a.get('refit_timeout_s',4.0)))
        else:model=fit_bool_tree(revealed_train,int(a['max_depth']))
        fresh=0.0 if model is None else acc_logic_model(fam,model,blind)
        return {'organ':'LOGIC','selected_algorithm':a,'validation':sel['validation'],'model':model,'fresh_blind':fresh}

    def meta_evolve_thinking(self,fit_traces,validation_blind,revealed_traces,blind):
        candidates=[]
        roles=sorted({r for t in fit_traces for r in t})
        for a in self._algs('THINKING'):
            fam=a['family'];threshold=float(a.get('threshold',.5))
            if fam=='GLOBAL_PRECEDENCE':model=learn_edges(fit_traces,threshold,int(a.get('min_support',2)))
            elif fam=='CONTEXTUAL_PRECEDENCE':
                for marker in roles:
                    p=[t for t in fit_traces if marker in t];q=[t for t in fit_traces if marker not in t]
                    if len(p)<2 or len(q)<2:continue
                    m={'kind':'CONTEXTUAL_PRECEDENCE','marker':marker,'present_edges':learn_edges(p,threshold,2),'absent_edges':learn_edges(q,threshold,2)}
                    candidates.append({'algorithm':dict(a,marker=marker),'model':m,'validation':plan_acc(m,validation_blind)})
                continue
            else:continue
            candidates.append({'algorithm':a,'model':model,'validation':plan_acc(model,validation_blind)})
        if not candidates:raise RuntimeError('no THINKING meta algorithms')
        sel=max(candidates,key=lambda z:(z['validation'],z['algorithm']['family']=='GLOBAL_PRECEDENCE',-len(json.dumps(z['model'],sort_keys=True))))
        a=sel['algorithm'];th=float(a.get('threshold',.5))
        if a['family']=='GLOBAL_PRECEDENCE':model=learn_edges(revealed_traces,th,int(a.get('min_support',2)))
        else:
            marker=a['marker'];p=[t for t in revealed_traces if marker in t];q=[t for t in revealed_traces if marker not in t]
            model={'kind':'CONTEXTUAL_PRECEDENCE','marker':marker,'present_edges':learn_edges(p,th,2),'absent_edges':learn_edges(q,th,2)}
        return {'organ':'THINKING','selected_algorithm':a,'validation':sel['validation'],'model':model,'fresh_blind':plan_acc(model,blind)}

    def meta_evolve_intelligence(self,fit,validation,revealed_train,blind):
        candidates=[]
        for a in self._algs('INTELLIGENCE'):
            fam=a['family']
            if fam=='CART_AXIS':model=fit_tree(fit,int(a['max_depth']));val=tree_acc(model,validation)
            elif fam=='LINEAR_SCORE_SEARCH':
                model=fit_linear(fit);val=0.0 if model is None else linear_acc(model,validation)
            else:continue
            candidates.append({'algorithm':a,'model':model,'validation':val})
        if not candidates:raise RuntimeError('no INTELLIGENCE meta algorithms')
        sel=max(candidates,key=lambda z:(z['validation'],z['algorithm']['family']=='CART_AXIS',-(z['algorithm'].get('max_depth') or 99)))
        a=sel['algorithm']
        if a['family']=='CART_AXIS':model=fit_tree(revealed_train,int(a['max_depth']));fresh=tree_acc(model,blind)
        else:model=fit_linear(revealed_train);fresh=0.0 if model is None else linear_acc(model,blind)
        return {'organ':'INTELLIGENCE','selected_algorithm':a,'validation':sel['validation'],'model':model,'fresh_blind':fresh}

    def meta_evolution_snapshot(self):
        b=self.organ_evolution_algorithm_bank()
        return {'profile':self.PROFILE,'enabled':bool(self.canonical_state.get('evolution_of_evolution_enabled')),
                'algorithm_counts':{k:len(v) for k,v in b.items()},'selection_policy':self.canonical_state.get('evolution_of_evolution_policy')}
    def unified_snapshot(self):
        s=super().unified_snapshot();s.update({'profile':self.PROFILE,'evolution_of_evolution':self.meta_evolution_snapshot()});return s

def meta_evolve_thinking(self,fit_traces,validation_blind,revealed_traces,blind):
        candidates=[]
        roles=sorted({r for t in fit_traces for r in t})
        for a in self._algs('THINKING'):
            fam=a['family'];threshold=float(a.get('threshold',.5))
            if fam=='GLOBAL_PRECEDENCE':model=learn_edges(fit_traces,threshold,int(a.get('min_support',2)))
            elif fam=='CONTEXTUAL_PRECEDENCE':
                for marker in roles:
                    p=[t for t in fit_traces if marker in t];q=[t for t in fit_traces if marker not in t]
                    if len(p)<2 or len(q)<2:continue
                    m={'kind':'CONTEXTUAL_PRECEDENCE','marker':marker,'present_edges':learn_edges(p,threshold,2),'absent_edges':learn_edges(q,threshold,2)}
                    candidates.append({'algorithm':dict(a,marker=marker),'model':m,'validation':plan_acc(m,validation_blind)})
                continue
            else:continue
            candidates.append({'algorithm':a,'model':model,'validation':plan_acc(model,validation_blind)})
        if not candidates:raise RuntimeError('no THINKING meta algorithms')
        sel=max(candidates,key=lambda z:(z['validation'],z['algorithm']['family']=='GLOBAL_PRECEDENCE',-len(json.dumps(z['model'],sort_keys=True))))
        a=sel['algorithm'];th=float(a.get('threshold',.5))
        if a['family']=='GLOBAL_PRECEDENCE':model=learn_edges(revealed_traces,th,int(a.get('min_support',2)))
        else:
            marker=a['marker'];p=[t for t in revealed_traces if marker in t];q=[t for t in revealed_traces if marker not in t]
            model={'kind':'CONTEXTUAL_PRECEDENCE','marker':marker,'present_edges':learn_edges(p,th,2),'absent_edges':learn_edges(q,th,2)}
