class EvolutionArchiveRuntime:
    """Bounded archive/lineage selector derived from external research principles.

    The runtime does not edit code or execute third-party artifacts. It stores evaluated
    variants, enforces hard admission constraints, preserves stepping stones, and emits
    a bounded operation suggestion (CLONAL, REACTION_NORM, CROSS_LINEAGE) from recorded
    task evidence. All mutation/execution remains outside this class and must pass the
    caller's existing verification/rollback gates.
    """
    REQUIRED_CONSTRAINTS=("regression_pass","state_integrity","rollback_available")

    def __init__(self, variants: Iterable[EvolutionVariant]=()):
        self._variants: Dict[str,EvolutionVariant]={}
        for v in variants:
            self.add(v)

    def add(self,v:EvolutionVariant)->None:
        if not v.variant_id or not v.lineage_id or not v.artifact_digest:
            raise ValueError("variant_id, lineage_id and artifact_digest are required")
        if v.variant_id in self._variants and self._variants[v.variant_id].canonical()!=v.canonical():
            raise ValueError("variant_id collision with different content")
        self._variants[v.variant_id]=v

    def variants(self)->List[EvolutionVariant]:
        return [self._variants[k] for k in sorted(self._variants)]

    def admitted(self,v:EvolutionVariant)->bool:
        return all(bool(v.constraints.get(k,False)) for k in self.REQUIRED_CONSTRAINTS)

    def archive_digest(self)->str:
        return digest_obj([v.canonical() for v in self.variants()])

    @staticmethod
    def _mean(xs:Sequence[float])->float:
        return sum(xs)/len(xs) if xs else 0.0

    def reaction_norm(self,variant_id:str, failure_threshold:float=0.5)->Dict[str,Any]:
        v=self._variants[variant_id]
        weak=sorted(k for k,s in v.task_scores.items() if float(s)<failure_threshold)
        recurring=sorted(set(weak)&set(map(str,v.failure_tags)))
        return {
            "variant_id":variant_id,
            "weak_tasks":weak,
            "recurring_failure_tags":recurring,
            "multi_task_weakness":len(weak)>=2,
            "mean_task_score":self._mean([float(x) for x in v.task_scores.values()]),
        }

    def cross_lineage_reference(self,target_variant_id:str,target_task:str)->Optional[Dict[str,Any]]:
        t=self._variants[target_variant_id]
        base=float(t.task_scores.get(target_task,0.0))
        rows=[]
        for v in self.variants():
            if v.lineage_id==t.lineage_id or not self.admitted(v):
                continue
            score=float(v.task_scores.get(target_task,0.0))
            if score<=base: continue
            mean=self._mean([float(x) for x in v.task_scores.values()])
            rows.append((score,mean,-len(v.failure_tags),v.variant_id,v))
        if not rows:return None
        _,_,_,_,v=max(rows)
        return {"variant_id":v.variant_id,"lineage_id":v.lineage_id,"target_task":target_task,
                "target_score":float(v.task_scores.get(target_task,0.0)),"target_base":base}

    def select_parent(self,target_task:str,trait_preferences:Optional[Mapping[str,float]]=None)->Dict[str,Any]:
        prefs={str(k):float(v) for k,v in (trait_preferences or {}).items()}
        rows=[]
        for v in self.variants():
            if not self.admitted(v):continue
            target=float(v.task_scores.get(target_task,0.0))
            mean=self._mean([float(x) for x in v.task_scores.values()])
            trait=sum(float(v.traits.get(k,0.0))*w for k,w in prefs.items())
            # target evidence dominates; mean guards against narrow overfit; traits are bounded tie-break evidence.
            utility=0.70*target+0.25*mean+0.05*trait
            rows.append((utility,target,mean,trait,-len(v.failure_tags),v.variant_id,v))
        if not rows:return {"action":"SEEK_MORE_EVIDENCE","reason":"NO_ADMITTED_VARIANTS"}
        row=max(rows)
        v=row[-1]
        return {"action":"SELECT_PARENT","variant_id":v.variant_id,"lineage_id":v.lineage_id,
                "utility":row[0],"target_score":row[1],"mean_score":row[2],"trait_score":row[3],
                "archive_digest":self.archive_digest()}

    def propose_operation(self,target_variant_id:str,target_task:str)->Dict[str,Any]:
        rn=self.reaction_norm(target_variant_id)
        if rn["multi_task_weakness"]:
            return {"operation":"REACTION_NORM","variant_id":target_variant_id,
                    "evidence":{"weak_tasks":rn["weak_tasks"],"mean_task_score":rn["mean_task_score"]}}
        ref=self.cross_lineage_reference(target_variant_id,target_task)
        if ref:
            return {"operation":"CROSS_LINEAGE","variant_id":target_variant_id,"reference":ref}
        return {"operation":"CLONAL","variant_id":target_variant_id,"target_task":target_task}

    def pareto_stepping_stones(self, objectives:Sequence[Tuple[str,str]])->List[str]:
        """Return non-dominated admitted variants. Objective kind is task:<name> or trait:<name>, direction max/min."""
        vs=[v for v in self.variants() if self.admitted(v)]
        def val(v:EvolutionVariant,key:str)->float:
            kind,name=key.split(':',1)
            return float(v.task_scores.get(name,0.0) if kind=='task' else v.traits.get(name,0.0))
        keep=[]
        for a in vs:
            dominated=False
            for b in vs:
                if a.variant_id==b.variant_id:continue
                weak=True;strict=False
                for key,direction in objectives:
                    av,bv=val(a,key),val(b,key)
                    if direction=='max':
                        weak &= bv>=av; strict |= bv>av
                    elif direction=='min':
                        weak &= bv<=av; strict |= bv<av
                    else: raise ValueError('direction must be max or min')
                if weak and strict:
                    dominated=True;break
            if not dominated:keep.append(a.variant_id)
        return sorted(keep)

    def snapshot(self)->Dict[str,Any]:
        return {"schema":"yado.evolution_archive.runtime.v1","variant_count":len(self._variants),
                "admitted_count":sum(self.admitted(v) for v in self._variants.values()),
                "archive_digest":self.archive_digest(),"variants":[v.canonical() for v in self.variants()]}

def fit_linear(cases):
    if not cases:return None
    keys=sorted({k for x,_ in cases for k in x})
    labels=sorted({y for _,y in cases},key=str)
    if len(labels)!=2:return None
    best=None
    for weights in itertools.product((-1.0,0.0,1.0),repeat=len(keys)):
        if not any(weights):continue
        vals=[sum(w*float(x.get(k,0.0)) for w,k in zip(weights,keys)) for x,_ in cases]
        unique=sorted(set(vals))
        thresholds=[(a+b)/2 for a,b in zip(unique,unique[1:])] or [0.0]
        for th in thresholds:
            for orient in (1,-1):
                preds=[labels[1] if orient*v>orient*th else labels[0] for v in vals]
                acc=sum(p==y for p,(_,y) in zip(preds,cases))/len(cases)
                cand=(acc,-sum(abs(w) for w in weights),tuple(weights),-abs(th),orient,th)
                model={'kind':'LINEAR_SCORE','features':keys,'weights':list(weights),'threshold':th,
                       'orientation':orient,'low_label':labels[0],'high_label':labels[1]}
                if best is None or cand>best[0]:best=(cand,model)
    return None if best is None else best[1]

class UnifiedYADOKernelV30RC6R2NativeExternal(UnifiedYADOKernelV30RC6R1RealExternal):
    """Native bounded R2 bridge re-derived from the durable state/consumer contract.

    It preserves the R2 public behavior needed by R3 without depending on the
    compatibility-recovery bridge module. This is a new implementation, not a
    claim that the lost historical source was recovered.
    """
    PROFILE = 'YADO_V3_0_RC6_R2_REAL_EXTERNAL_TRAINED_LOCAL'
    SCHEMA_VERSION = 21

    def __init__(self, db_path='yado_v30_rc6_r2_real_external.db', state_path=None):
        super().__init__(db_path=db_path, state_path=state_path or str(DEFAULT_STATE))

    def logic_registry(self):
        return dict(self.real_external_registry().get('LOGIC') or {})

    def predict_external_logic(self, features: Mapping[str, object]):
        model = self.logic_registry().get('serialized_model')
        if not isinstance(model, dict):
            return {'action': 'SEEK_MORE_EVIDENCE', 'reason': 'NO_DURABLE_LOGIC_MODEL'}
        return {
            'action': 'USE_MODEL',
            'prediction': bool(tree_predict(model, dict(features))),
            'representation_version': self.logic_registry().get('representation_version'),
        }

    def route_external_text(self, text: str):
        cfg = self.real_external_registry().get('INTELLIGENCE', {})
        n = int(cfg.get('ngram_n', 3))
        profiles = cfg.get('centroid_profiles') or {}
        grams = self._grams(text, n)
        scores = {name: self._cos(grams, self._grams(profile, n)) for name, profile in profiles.items()}
        if len(scores) < 2:
            return {
                'action': 'SEEK_MORE_EVIDENCE',
                'scores': scores,
                'margin': 0.0,
                'top_score': max(scores.values(), default=0.0),
            }
        ranked = sorted(scores.items(), key=lambda z: (z[1], z[0]), reverse=True)
        margin = ranked[0][1] - ranked[1][1]
        top = ranked[0][1]
        margin_min = float(cfg.get('defer_margin', 1.0))
        top_min = float(cfg.get('top_score_min', 0.0))
        accepted = margin >= margin_min and top >= top_min
        return {
            'action': 'USE_ROUTE' if accepted else 'SEEK_MORE_EVIDENCE',
            'route': ranked[0][0] if accepted else None,
            'top_candidate': ranked[0][0],
            'margin': margin,
            'threshold': margin_min,
            'top_score': top,
            'top_score_min': top_min,
            'scores': scores,
        }

    def unified_snapshot(self):
        snapshot = super().unified_snapshot()
        snapshot.update({'profile': self.PROFILE, 'schema_version': self.SCHEMA_VERSION, 'r2_logic': self.logic_registry()})
        return snapshot

def _predicate(program,features):
    if program['kind']=='BOOL_TABLE':
        a,b=program['signals']; key=f"{int(bool(features.get(a,False)))}{int(bool(features.get(b,False)))}"
        return bool(program['table'][key])
    return sum(w*float(features.get(k,0)) for w,k in zip(program['weights'],program['signals']))>program['threshold']

def _linear_candidates(cases):
    keys=sorted({k for x,*_ in cases for k in (x if isinstance(x,dict) else {})})
    for a,b in itertools.combinations(keys,2):
        vals=[(float(x.get(a,0)),float(x.get(b,0))) for x,*_ in cases]
        for wa,wb in itertools.product((-1.0,1.0),repeat=2):
            scores=sorted(set(wa*u+wb*v for u,v in vals))
            for lo,hi in zip(scores,scores[1:]):
                yield {'kind':'LINEAR_THRESHOLD','signals':[a,b],'weights':[wa,wb],'threshold':(lo+hi)/2}

def synth_thinking_predicate(fit,val,revealed,blind,algs):
    candidates=[]
    for p in _linear_candidates(fit):
        def lift(rows):return [(dict(e[0],__REC=float(_predicate(p,e[0]))),*e[1:]) for e in rows]
        skeleton={'op':'IF_SIGNAL','signal':{'source':'EPISODE_CONTEXT','key':'__REC','threshold':.5},
                  'then':{'op':'LEAF'},'else':{'op':'LEAF'}}
        fitted=fit_thinking_skeleton(skeleton,lift(fit),algs)
        if fitted is None:continue
        model={'op':'IF_PREDICATE','predicate_program':p,'then':fitted['then'],'else':fitted['else']}
        candidates.append((thinking_component_acc(model,val),p))
    if not candidates:return {'status':'WITHHOLD'}
    validation,p=max(candidates,key=lambda z:z[0])
    skeleton={'op':'IF_SIGNAL','signal':{'source':'EPISODE_CONTEXT','key':'__REC','threshold':.5},
              'then':{'op':'LEAF'},'else':{'op':'LEAF'}}
    lifted=[(dict(e[0],__REC=float(_predicate(p,e[0]))),*e[1:]) for e in revealed]
    fitted=fit_thinking_skeleton(skeleton,lifted,algs)
    if fitted is None:
        return {'status':'WITHHOLD','reason':'REVEALED_PARTITION_COLLAPSE'}
    model={'op':'IF_PREDICATE','predicate_program':p,'then':fitted['then'],'else':fitted['else']}
    return {'status':'SUPPORTED','grammar_extension_id':_gid(p),'predicate_program':p,'model':model,
            'validation':validation,'fresh_blind':thinking_component_acc(model,blind)}

class MetacognitiveController:
    def __init__(self, execute_threshold:float=0.66, evidence_threshold:float=0.45, disagreement_threshold:float=0.20):
        self.execute_threshold=float(execute_threshold)
        self.evidence_threshold=float(evidence_threshold)
        self.disagreement_threshold=float(disagreement_threshold)
    def decide(self,task:MetacognitiveTask,profile:CapabilityBoundaryProfile)->MetacognitiveDecision:
        v=max(0.0,min(1.0,float(task.verbal_confidence)))
        e=max(0.0,min(1.0,float(task.evidence_coverage)))
        n=max(0.0,min(1.0,float(task.novelty)))
        p=profile.confidence(task.capability,task.difficulty)
        d=abs(v-p)
        if task.framework_conflict:
            return MetacognitiveDecision('ROUTE_FRAMEWORK',min(v,p),p,d,'EPISTEMIC_FRAMEWORK_CONFLICT')
        if e < self.evidence_threshold:
            return MetacognitiveDecision('SEEK_EVIDENCE',min(v,p,e),p,d,'INSUFFICIENT_EVIDENCE')
        score=0.25*v+0.55*p+0.20*e
        score-=0.30*max(0.0,d-self.disagreement_threshold)
        score-=0.16*n
        score=max(0.0,min(1.0,score))
        if score >= self.execute_threshold:
            return MetacognitiveDecision('EXECUTE',score,p,d,'CAPABILITY_AND_EVIDENCE_ALIGNED')
        return MetacognitiveDecision('WITHHOLD',score,p,d,'CAPABILITY_BOUNDARY_OR_DISTRIBUTION_SHIFT')
    @staticmethod
    def feedback(profile:CapabilityBoundaryProfile,task:MetacognitiveTask,success:bool):
        profile.update(CapabilityObservation(task.capability,task.difficulty,bool(success)))

